<?php
declare(strict_types=1);$pageTitle='My Giving';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/_helpers.php';require_once __DIR__.'/_listing.php';require_permission('member.giving.view');$mid=current_member_id();$tab=(string)($_GET['tab']??'offertory');$tabs=['offertory'=>'Offertory','tithe'=>'Tithe','thanksgiving'=>'Thanksgiving','pledges'=>'Pledges','contributions'=>'Contributions','good_samaritan'=>'Good Samaritan'];if(!isset($tabs[$tab]))$tab='offertory';
$defs=['offertory'=>['offertory','SELECT service_date,service_type,total_amount,payment_method FROM offertory WHERE member_id=? ORDER BY service_date DESC'],'tithe'=>['tithe','SELECT receipt_no,tithe_date,amount,payment_method FROM tithe WHERE member_id=? ORDER BY tithe_date DESC'],'thanksgiving'=>['thanksgiving','SELECT receipt_no,thanksgiving_date,amount,payment_method,item_description FROM thanksgiving WHERE member_id=? ORDER BY thanksgiving_date DESC'],'pledges'=>['pledges','SELECT pledge_no,pledge_reason,amount,amount_paid,balance,due_date,status FROM pledges WHERE member_id=? ORDER BY created_at DESC'],'contributions'=>['contributions','SELECT receipt_no,amount,payment_method,contributed_on,notes FROM contributions WHERE member_id=? ORDER BY contributed_on DESC'],'good_samaritan'=>['good_samaritan','SELECT receipt_no,amount,payment_method,given_on,notes FROM good_samaritan WHERE member_id=? ORDER BY given_on DESC, id DESC']];$rows=[];if(mp_table($conn,$defs[$tab][0]))$rows=mp_rows($conn,$defs[$tab][1],'i',[$mid]);
$total=0;$paid=0;$balance=0;foreach($rows as $r){$total+=(float)($r['amount']??0);$paid+=(float)($r['amount_paid']??0);$balance+=(float)($r['balance']??0);} $stats=[['label'=>'Records','value'=>count($rows),'icon'=>'fa-receipt'],['label'=>'Total Amount','value'=>$total,'icon'=>'fa-coins','money'=>true]];if($tab==='pledges'){$stats[]=['label'=>'Amount Paid','value'=>$paid,'icon'=>'fa-circle-check','money'=>true];$stats[]=['label'=>'Balance','value'=>$balance,'icon'=>'fa-hourglass-half','money'=>true];}
include __DIR__.'/../includes/sidebar.php';?><div class="main-content"><?php include __DIR__.'/../includes/topbar.php';?><div class="content-wrapper"><div class="card"><div class="card-header"><h3>My Giving</h3></div><div class="card-body"><?php mp_tabs($tabs,$tab);mp_render_listing_page('My '.$tabs[$tab],'Only transactions recorded against your member profile are shown.',$rows,$stats);?></div></div></div></div><?php mp_standard_styles();require_once __DIR__.'/../includes/footer.php';?>
